package com.northstar.crm.ui;

import com.northstar.crm.domain.*;import com.northstar.crm.security.ActorResolver;import com.northstar.crm.service.*;import com.vaadin.flow.component.*;import com.vaadin.flow.component.button.*;import com.vaadin.flow.component.combobox.ComboBox;import com.vaadin.flow.component.dialog.Dialog;import com.vaadin.flow.component.formlayout.FormLayout;import com.vaadin.flow.component.grid.Grid;import com.vaadin.flow.component.html.*;import com.vaadin.flow.component.orderedlayout.*;import com.vaadin.flow.component.select.Select;import com.vaadin.flow.component.tabs.*;import com.vaadin.flow.component.textfield.*;import com.vaadin.flow.component.upload.*;import com.vaadin.flow.component.upload.receivers.MemoryBuffer;import com.vaadin.flow.data.binder.*;import com.vaadin.flow.data.renderer.ComponentRenderer;import com.vaadin.flow.router.*;import com.vaadin.flow.server.StreamResource;import jakarta.annotation.security.PermitAll;import java.io.*;import java.math.BigDecimal;import java.time.LocalDate;import java.util.*;import static com.northstar.crm.domain.DomainTypes.*;
@Route(value="organizations/:id",layout=MainLayout.class) @PageTitle("Organization · Northstar") @PermitAll public class OrganizationDetailView extends VerticalLayout implements BeforeEnterObserver {
 private final OrganizationService organizations;private final ContactService contacts;private final DealService deals;private final EscalationService escalations;private final DocumentService documents;private final IntegrationService integrations;private final AccountService accounts;private final ActorResolver actors;private Organization org;private final Div body=new Div();
 public OrganizationDetailView(OrganizationService o,ContactService c,DealService d,EscalationService e,DocumentService docs,IntegrationService i,AccountService a,ActorResolver actors){organizations=o;contacts=c;deals=d;escalations=e;documents=docs;integrations=i;accounts=a;this.actors=actors;setPadding(false);setSizeFull();}
 @Override public void beforeEnter(BeforeEnterEvent event){try{org=organizations.getAuthorized(UUID.fromString(event.getRouteParameters().get("id").orElseThrow()));render();}catch(Exception e){event.rerouteToError(org.springframework.security.access.AccessDeniedException.class,"This organization is unavailable");}}
 private void render(){removeAll();var actor=actors.current();var back=new RouterLink("← Organizations",OrganizationsView.class);var title=new HorizontalLayout(new Div(new Span(org.getPlan()+" PLAN"),new H1(org.getName()),new Paragraph("Renews "+org.getRenewalDate()+" · "+org.getBillingEmail())),UiKit.badge(org.getHealth()));title.addClassName("detail-title");title.setWidthFull();title.expand(title.getComponentAt(0));var tabs=new Tabs();var overview=new Tab("Overview");var contactTab=new Tab("Contacts");var dealTab=new Tab("Deals & renewals");var escalationTab=new Tab("Escalations");var docTab=new Tab("Documents");tabs.add(overview,contactTab);if(actor.getRole()!=Role.CUSTOMER_CONTACT)tabs.add(dealTab);tabs.add(escalationTab,docTab);Tab integrationTab=null;if(actor.getRole()==Role.PLATFORM_ADMIN||actor.getRole()==Role.ACCOUNT_MANAGER){integrationTab=new Tab("API & webhooks");tabs.add(integrationTab);}var it=integrationTab;tabs.addSelectedChangeListener(e->{if(e.getSelectedTab()==overview)showOverview();else if(e.getSelectedTab()==contactTab)showContacts();else if(e.getSelectedTab()==dealTab)showDeals();else if(e.getSelectedTab()==escalationTab)showEscalations();else if(e.getSelectedTab()==docTab)showDocuments();else if(e.getSelectedTab()==it)showIntegrations();});body.addClassName("tab-body");add(UiKit.page("ACCOUNT RECORD",org.getName(),"A scoped customer workspace. Sensitive controls are enforced by the decision service.",back,title,tabs,body));showOverview();}
 private void show(Component component){body.removeAll();body.add(component);}
 private void showOverview(){var metrics=new Div(UiKit.metric("Health score",org.getHealthScore()+" / 100",UiKit.human(org.getHealth()),"metric-blue"),UiKit.metric("Renewal",org.getRenewalDate().toString(),days(org.getRenewalDate())+" days away","metric-amber"),UiKit.metric("Plan",org.getPlan(),UiKit.human(org.getStatus()),"metric-mint"));metrics.addClassName("metric-grid");var risk=new Div(new H3(actors.current().getRole()==Role.CUSTOMER_CONTACT?"Account status":"Renewal risk assessment"),new Paragraph(actors.current().getRole()==Role.CUSTOMER_CONTACT?"Your account team reviews service health and renewal readiness here.":org.getRiskSummary()));risk.addClassName("panel");show(new VerticalLayout(metrics,risk));}
 private void showContacts(){var grid=new Grid<Contact>();grid.addColumn(Contact::getName).setHeader("Name");grid.addColumn(Contact::getTitle).setHeader("Role");grid.addColumn(Contact::getEmail).setHeader("Email");grid.addColumn(c->c.isPortalAccess()?"Portal enabled":"No portal").setHeader("Access");grid.addComponentColumn(c->new Button("Portal code",e->portalCodeDialog(grid,c))).setHeader("Code");grid.setItems(contacts.forOrganization(org.getId()));grid.setAllRowsVisible(true);var actions=new HorizontalLayout();if(actors.current().getRole()!=Role.CUSTOMER_CONTACT){actions.add(UiKit.primary("Add contact",e->contactDialog(grid)),new Button("Invite contact",e->inviteDialog()));}var panel=new VerticalLayout(actions,grid);panel.addClassName("panel");show(panel);}
 private void contactDialog(Grid<Contact> grid){var dialog=new Dialog();dialog.setHeaderTitle("Add customer contact");var name=new TextField("Name");var email=new EmailField("Email");var phone=new TextField("Phone");var title=new TextField("Title");var billing=new com.vaadin.flow.component.checkbox.Checkbox("Billing contact");var portal=new com.vaadin.flow.component.checkbox.Checkbox("Portal access");var bean=new ContactForm();var binder=new Binder<ContactForm>();binder.forField(name).asRequired().bind(ContactForm::getName,ContactForm::setName);binder.forField(email).asRequired().bind(ContactForm::getEmail,ContactForm::setEmail);binder.forField(phone).bind(ContactForm::getPhone,ContactForm::setPhone);binder.forField(title).bind(ContactForm::getTitle,ContactForm::setTitle);binder.forField(billing).bind(ContactForm::isBilling,ContactForm::setBilling);binder.forField(portal).bind(ContactForm::isPortal,ContactForm::setPortal);binder.setBean(bean);dialog.add(new FormLayout(name,email,phone,title,billing,portal));dialog.getFooter().add(new Button("Cancel",e->dialog.close()),UiKit.primary("Add contact",e->{try{if(!binder.validate().isOk())return;contacts.create(org.getId(),new ContactService.ContactInput(bean.name,bean.email,bean.phone,bean.title,bean.billing,bean.portal));grid.setItems(contacts.forOrganization(org.getId()));dialog.close();UiKit.success("Contact added");}catch(Exception ex){UiKit.error(ex);}}));dialog.open();}
 private void portalCodeDialog(Grid<Contact> grid,Contact c){var code=new com.vaadin.flow.component.textfield.PasswordField("Portal access code");code.setWidthFull();var dialog=new Dialog();dialog.setHeaderTitle("Portal access code for "+c.getName());dialog.add(new Paragraph("The contact enters this code to open shared documents."),code);dialog.getFooter().add(new Button("Cancel",e->dialog.close()),UiKit.primary("Save code",e->{try{contacts.setPortalCode(c.getId(),code.getValue());dialog.close();UiKit.success("Portal access code updated");}catch(Exception ex){UiKit.error(ex);}}));dialog.open();}
 private void inviteDialog(){var email=new EmailField("Contact email");email.setWidthFull();var dialog=new Dialog();dialog.setHeaderTitle("Invite to customer portal");dialog.add(new Paragraph("A two-day, single-use invite will be written to the local email outbox."),email);dialog.getFooter().add(new Button("Cancel",e->dialog.close()),UiKit.primary("Create invitation",e->{try{accounts.inviteCustomer(org.getId(),email.getValue());dialog.close();UiKit.success("Invitation created in the email outbox");}catch(Exception ex){UiKit.error(ex);}}));dialog.open();}
 private void showDeals(){var grid=new Grid<Deal>();grid.addColumn(Deal::getName).setHeader("Deal / renewal").setFlexGrow(2);grid.addColumn(new ComponentRenderer<>(d->UiKit.badge(d.getStage()))).setHeader("Stage");grid.addColumn(d->d.getCurrency()+" "+d.getValue()).setHeader("Value");grid.addColumn(d->d.getProbability()+"%").setHeader("Probability");grid.addColumn(Deal::getCloseDate).setHeader("Close date");grid.addComponentColumn(d->{var next=new ComboBox<DealStage>();next.setItems(DealService.ALLOWED_TRANSITIONS.getOrDefault(d.getStage(),Set.of()));next.setPlaceholder("Move to…");next.setWidth("160px");next.addValueChangeListener(e->{if(e.getValue()!=null)try{deals.transition(d.getId(),e.getValue());grid.setItems(deals.forOrganization(org.getId()));UiKit.success("Deal stage updated");}catch(Exception ex){UiKit.error(ex);}});return next;}).setHeader("Workflow");grid.addComponentColumn(d->new Button("Reinstate as won",e->reinstateDialog(grid,d))).setHeader("Renewal");grid.setItems(deals.forOrganization(org.getId()));grid.setAllRowsVisible(true);var panel=new VerticalLayout(UiKit.primary("New deal",e->dealDialog(grid)),grid);panel.addClassName("panel");show(panel);}
 private void dealDialog(Grid<Deal> grid){var dialog=new Dialog();dialog.setHeaderTitle("Create deal");var name=new TextField("Name");var value=new BigDecimalField("Value (GBP)");var probability=new IntegerField("Probability (%)");probability.setMin(0);probability.setMax(100);var close=new com.vaadin.flow.component.datepicker.DatePicker("Close date");var notes=new TextArea("Internal notes");var bean=new DealForm();var binder=new Binder<DealForm>();binder.forField(name).asRequired().bind(DealForm::getName,DealForm::setName);binder.forField(value).asRequired().bind(DealForm::getValue,DealForm::setValue);binder.forField(probability).asRequired().bind(DealForm::getProbability,DealForm::setProbability);binder.forField(close).asRequired().bind(DealForm::getCloseDate,DealForm::setCloseDate);binder.forField(notes).bind(DealForm::getNotes,DealForm::setNotes);binder.setBean(bean);dialog.add(new FormLayout(name,value,probability,close,notes));dialog.getFooter().add(new Button("Cancel",e->dialog.close()),UiKit.primary("Create deal",e->{try{if(!binder.validate().isOk())return;deals.create(org.getId(),new DealService.DealInput(bean.name,bean.value,bean.probability,bean.closeDate,bean.notes));grid.setItems(deals.forOrganization(org.getId()));dialog.close();UiKit.success("Deal created at Lead stage");}catch(Exception ex){UiKit.error(ex);}}));dialog.open();}
 private void reinstateDialog(Grid<Deal> grid,Deal deal){var reference=new TextField("Signed order form reference");reference.setWidthFull();var dialog=new Dialog();dialog.setHeaderTitle("Reinstate renewal as won");dialog.add(new Paragraph("Record the countersigned order form that closes "+deal.getName()+"."),reference);dialog.getFooter().add(new Button("Cancel",e->dialog.close()),UiKit.primary("Reinstate",e->{try{deals.reinstateRenewal(deal.getId(),reference.getValue());grid.setItems(deals.forOrganization(org.getId()));dialog.close();UiKit.success("Renewal reinstated as won");}catch(Exception ex){UiKit.error(ex);}}));dialog.open();}
 private void showEscalations(){var grid=new Grid<Escalation>();grid.addColumn(Escalation::getSubject).setHeader("Request").setFlexGrow(2);grid.addColumn(new ComponentRenderer<>(e->UiKit.badge(e.getSeverity()))).setHeader("Severity");grid.addColumn(new ComponentRenderer<>(e->UiKit.badge(e.getStatus()))).setHeader("Status");grid.setItems(escalations.queue().stream().filter(e->e.getOrganizationId().equals(org.getId())).toList());grid.addItemClickListener(e->UI.getCurrent().navigate("escalations/"+e.getItem().getId()));grid.setAllRowsVisible(true);var panel=new VerticalLayout(UiKit.primary("Open escalation",e->escalationDialog(grid)),grid);panel.addClassName("panel");show(panel);}
 private void escalationDialog(Grid<Escalation> grid){var subject=new TextField("Subject");var severity=new ComboBox<Severity>("Severity");severity.setItems(Severity.values());var summary=new TextArea("Customer-visible summary");summary.setWidthFull();var dialog=new Dialog();dialog.setHeaderTitle("Open escalation");dialog.add(new FormLayout(subject,severity,summary));dialog.getFooter().add(new Button("Cancel",e->dialog.close()),UiKit.primary("Open escalation",e->{try{escalations.create(org.getId(),subject.getValue(),severity.getValue(),summary.getValue());dialog.close();showEscalations();UiKit.success("Escalation opened");}catch(Exception ex){UiKit.error(ex);}}));dialog.open();}
 private void showDocuments(){var grid=new Grid<CustomerDocument>();grid.addColumn(CustomerDocument::getDisplayName).setHeader("Document").setFlexGrow(2);grid.addColumn(d->UiKit.human(d.getCategory())).setHeader("Category");grid.addColumn(new ComponentRenderer<>(d->UiKit.badge(d.getVisibility()))).setHeader("Visibility");grid.addColumn(d->Math.max(1,d.getSizeBytes()/1024)+" KB").setHeader("Size");grid.addComponentColumn(d->{var resource=new StreamResource(d.getDisplayName(),()->documents.download(d.getId()).stream());resource.setContentType(d.getContentType());var a=new Anchor(resource,"Download");a.getElement().setAttribute("download",true);return a;}).setHeader("Action");grid.setItems(documents.forOrganization(org.getId()));grid.setAllRowsVisible(true);var panel=new VerticalLayout();if(actors.current().getRole()!=Role.CUSTOMER_CONTACT)panel.add(uploadControl(grid));panel.add(grid);panel.addClassName("panel");show(panel);}
 private Component uploadControl(Grid<CustomerDocument> grid){var buffer=new MemoryBuffer();var upload=new Upload(buffer);upload.setAcceptedFileTypes("application/pdf","text/plain","text/csv","application/vnd.openxmlformats-officedocument.wordprocessingml.document");upload.setMaxFileSize(10*1024*1024);var category=new ComboBox<DocumentCategory>("Category");category.setItems(DocumentCategory.values());category.setValue(DocumentCategory.CONTRACT);var visibility=new ComboBox<Visibility>("Visibility");visibility.setItems(Visibility.values());visibility.setValue(Visibility.INTERNAL);var tags=new TextField("Tags");upload.addSucceededListener(e->{try{documents.upload(org.getId(),e.getFileName(),e.getMIMEType(),buffer.getInputStream().readAllBytes(),category.getValue(),visibility.getValue(),tags.getValue());grid.setItems(documents.forOrganization(org.getId()));UiKit.success("Document uploaded");}catch(Exception ex){UiKit.error(ex);}});var fromUrl=new Button("Import from URL",e->importUrlDialog(grid,category,visibility,tags));var packetBuffer=new MemoryBuffer();var packet=new Upload(packetBuffer);packet.setMaxFileSize(10*1024*1024);packet.setDropLabel(new Span("Partner packet"));packet.addSucceededListener(e->{try{documents.stagePartnerPacket(org.getId(),e.getFileName(),packetBuffer.getInputStream().readAllBytes(),category.getValue(),visibility.getValue(),tags.getValue());grid.setItems(documents.forOrganization(org.getId()));UiKit.success("Partner packet filed");}catch(Exception ex){UiKit.error(ex);}});var box=new HorizontalLayout(upload,category,visibility,packet,tags,fromUrl);box.setAlignItems(Alignment.END);box.addClassName("upload-row");return box;}
 private void importUrlDialog(Grid<CustomerDocument> grid,ComboBox<DocumentCategory> category,ComboBox<Visibility> visibility,TextField tags){var source=new TextField("Source link");source.setWidthFull();var filename=new TextField("Save as");filename.setWidthFull();var dialog=new Dialog();dialog.setHeaderTitle("Import document from URL");dialog.add(new Paragraph("Northstar fetches the file from the source system and files it against this account."),source,filename);dialog.getFooter().add(new Button("Cancel",e->dialog.close()),UiKit.primary("Import",e->{try{documents.importFromUrl(org.getId(),source.getValue(),filename.getValue(),category.getValue(),visibility.getValue(),tags.getValue());grid.setItems(documents.forOrganization(org.getId()));dialog.close();UiKit.success("Document imported");}catch(Exception ex){UiKit.error(ex);}}));dialog.open();}
 private void showIntegrations(){var keyGrid=new Grid<ApiCredential>();keyGrid.addColumn(ApiCredential::getLabel).setHeader("Key");keyGrid.addColumn(k->k.getPrefix()+"••••••••").setHeader("Prefix");keyGrid.addColumn(new ComponentRenderer<>(k->UiKit.badge(k.getStatus()))).setHeader("Status");keyGrid.addColumn(ApiCredential::getScopes).setHeader("Scopes");keyGrid.addComponentColumn(k->new Button("Rotate",e->{try{var made=integrations.rotate(k.getId());secretDialog(made.secret());keyGrid.setItems(integrations.keys(org.getId()));}catch(Exception ex){UiKit.error(ex);}})).setHeader("Action");keyGrid.setItems(integrations.keys(org.getId()));keyGrid.setAllRowsVisible(true);var hooks=new Grid<WebhookEndpoint>();hooks.addColumn(WebhookEndpoint::getName).setHeader("Webhook");hooks.addColumn(WebhookEndpoint::getUrl).setHeader("Destination");hooks.addColumn(WebhookEndpoint::getEvents).setHeader("Events");hooks.addComponentColumn(h->new Button("Test delivery",e->{try{integrations.test(h.getId(),WebhookEvent.ESCALATION_UPDATED);UiKit.success("Local mock accepted the test delivery");}catch(Exception ex){UiKit.error(ex);}}));hooks.setItems(integrations.webhooks(org.getId()));hooks.setAllRowsVisible(true);var panel=new VerticalLayout(new H3("API keys"),UiKit.primary("Create API key",e->keyDialog(keyGrid)),keyGrid,new H3("Webhook notifications"),UiKit.primary("Add webhook",e->webhookDialog(hooks)),hooks,UiKit.primary("Sync reporting record",e->{try{UiKit.success(integrations.pushAccountSummary(org.getId()));}catch(Exception ex){UiKit.error(ex);}}));panel.addClassName("panel");show(panel);}
 private void keyDialog(Grid<ApiCredential> grid){var label=new TextField("Key label");var scopes=new com.vaadin.flow.component.checkbox.CheckboxGroup<String>("Scopes");scopes.setItems("organizations:read","escalations:read","documents:read");var dialog=new Dialog();dialog.setHeaderTitle("Create API key");dialog.add(label,scopes);dialog.getFooter().add(new Button("Cancel",e->dialog.close()),UiKit.primary("Create key",e->{try{var made=integrations.createKey(org.getId(),label.getValue(),String.join(",",scopes.getValue()));dialog.close();grid.setItems(integrations.keys(org.getId()));secretDialog(made.secret());}catch(Exception ex){UiKit.error(ex);}}));dialog.open();}
 private void secretDialog(String secret){var field=new TextField("Secret—shown once");field.setValue(secret);field.setReadOnly(true);field.setWidthFull();var d=new Dialog();d.setHeaderTitle("Store this API key now");d.add(new Paragraph("Northstar stores only a BCrypt hash. This value cannot be recovered later."),field);d.getFooter().add(UiKit.primary("I’ve stored it",e->d.close()));d.setCloseOnOutsideClick(false);d.open();}
 private void webhookDialog(Grid<WebhookEndpoint> grid){var name=new TextField("Name");var url=new TextField("HTTPS local-mock URL");url.setHelperText("Example: https://billing.example.test/events");var events=new com.vaadin.flow.component.checkbox.CheckboxGroup<String>("Events");events.setItems(Arrays.stream(WebhookEvent.values()).map(Enum::name).toList());var probe=new Paragraph();var check=new Button("Check reachability",e->{try{probe.setText(integrations.checkReachability(url.getValue()));}catch(Exception ex){UiKit.error(ex);}});var d=new Dialog();d.setHeaderTitle("Add webhook");d.add(name,url,events,check,probe);d.getFooter().add(new Button("Cancel",e->d.close()),UiKit.primary("Add webhook",e->{try{integrations.createWebhook(org.getId(),name.getValue(),url.getValue(),String.join(",",events.getValue()));d.close();grid.setItems(integrations.webhooks(org.getId()));UiKit.success("Webhook added");}catch(Exception ex){UiKit.error(ex);}}));d.open();}
 private long days(LocalDate date){return java.time.temporal.ChronoUnit.DAYS.between(LocalDate.now(),date);}
 public static class ContactForm {String name="",email="",phone="",title="";boolean billing,portal;public String getName(){return name;}public void setName(String v){name=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getPhone(){return phone;}public void setPhone(String v){phone=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public boolean isBilling(){return billing;}public void setBilling(boolean v){billing=v;}public boolean isPortal(){return portal;}public void setPortal(boolean v){portal=v;}}
 public static class DealForm {String name="",notes="";BigDecimal value=BigDecimal.ZERO;Integer probability=50;LocalDate closeDate=LocalDate.now().plusMonths(3);public String getName(){return name;}public void setName(String v){name=v;}public String getNotes(){return notes;}public void setNotes(String v){notes=v;}public BigDecimal getValue(){return value;}public void setValue(BigDecimal v){value=v;}public Integer getProbability(){return probability;}public void setProbability(Integer v){probability=v;}public LocalDate getCloseDate(){return closeDate;}public void setCloseDate(LocalDate v){closeDate=v;}}
}
